{"content": "     1|import type { AgentSession, AgentSessionEvent } from '@mariozechner/pi-coding-agent';
     2|import type { AssistantMessage, Usage } from '@mariozechner/pi-ai';
     3|
     4|import type { MessageChunk, TokenUsage } from '../../types';
     5|import { AsyncQueue, type BridgeQueueItem } from '../../utils/async-queue';
     6|import { createLazyLogger } from '../../utils/lazy-logger';
     7|
     8|const getLog = createLazyLogger('provider.pi.event-bridge');
     9|
    10|/**
    11| * Serialize a tool-execution `result` payload to a stable string.
    12| * Pi tools return arbitrary JS — strings pass through, everything else is
    13| * JSON-serialized (with String() fallback for non-serializable objects).
    14| */
    15|export function serializeToolResult(result: unknown): string {
    16|  if (typeof result === 'string') return result;
    17|  try {
    18|    return JSON.stringify(result);
    19|  } catch {
    20|    return String(result);
    21|  }
    22|}
    23|
    24|/**
    25| * Extract Archon TokenUsage from Pi's Usage struct.
    26| * Pi reports input/output/cacheRead/cacheWrite + cost breakdown.
    27| */
    28|export function usageToTokens(usage: Usage): TokenUsage {
    29|  return {
    30|    input: usage.input,
    31|    output: usage.output,
    32|    total: usage.totalTokens,
    33|    cost: usage.cost.total,
    34|  };
    35|}
    36|
    37|/**
    38| * Narrow a single transcript message to AssistantMessage by inspecting
    39| * `role` and `usage` structurally. Pi's AgentMessage union includes user,
    40| * toolResult, and custom extension messages; we only care about assistant
    41| * messages for result-chunk assembly.
    42| */
    43|function isAssistantMessage(m: unknown): m is AssistantMessage {
    44|  if (m === null || typeof m !== 'object') return false;
    45|  const obj = m as { role?: unknown; usage?: unknown };
    46|  return obj.role === 'assistant' && typeof obj.usage === 'object' && obj.usage !== null;
    47|}
    48|
    49|/**
    50| * Build the terminal `result` chunk from the final `agent_end` event. Pulls
    51| * usage/stopReason/error from the last assistant message in the returned
    52| * transcript. When the agent ended in error, surfaces it as `isError: true`.
    53| */
    54|export function buildResultChunk(messages: readonly unknown[]): MessageChunk {
    55|  const last = [...messages].reverse().find(isAssistantMessage);
    56|  if (!last) {
    57|    // agent_end fired with no assistant message in the transcript. This
    58|    // shouldn't happen in healthy Pi runs — surface it as a loud error
    59|    // rather than a silent success so orchestrators don't treat a broken
    60|    // session as a clean completion.
    61|    getLog().warn('pi.event-bridge.result_missing_assistant_message');
    62|    return { type: 'result', isError: true, errorSubtype: 'missing_assistant_message' };
    63|  }
    64|
    65|  const tokens = usageToTokens(last.usage);
    66|  const isError = last.stopReason === 'error' || last.stopReason === 'aborted';
    67|
    68|  const chunk: MessageChunk = {
    69|    type: 'result',
    70|    tokens,
    71|    ...(tokens.cost !== undefined ? { cost: tokens.cost } : {}),
    72|    ...(last.stopReason ? { stopReason: last.stopReason } : {}),
    73|    ...(isError ? { isError: true, errorSubtype: last.stopReason } : {}),
    74|  };
    75|  return chunk;
    76|}
    77|
    78|/**
    79| * Attempt to parse a Pi assistant transcript as the structured-output JSON
    80| * requested via `outputFormat`. Handles three common model failure modes:
    81| *  - trailing/leading whitespace (always stripped)
    82| *  - markdown code fences (```json ... ``` or bare ``` ... ```) that models
    83| *    emit despite the "no code fences" instruction in the prompt
    84| *  - prose preamble followed by a single trailing JSON object — pattern
    85| *    observed on Minimax M2.7 ("Now I have all the inputs. Let me evaluate
    86| *    the three gates: ... {...}"). Reasoning models tend to "think out loud"
    87| *    before emitting structured output despite explicit JSON-only prompts.
    88| *
    89| * Returns the parsed value on success, `undefined` on any failure. Callers
    90| * treat `undefined` as "structured output unavailable" and degrade via the
    91| * dag-executor's existing missing-structured-output warning.
    92| */
    93|export function tryParseStructuredOutput(text: string): unknown {
    94|  const trimmed = text.trim();
    95|  if (trimmed.length === 0) return undefined;
    96|  // Strip ```json / ``` fences if present. Match only at boundaries so we
    97|  // don't mangle JSON strings that legitimately contain backticks.
    98|  const cleaned = trimmed
    99|    .replace(/^```(?:json)?\s*\n?/i, '')
   100|    .replace(/\n?\s*```\s*$/, '')
   101|    .trim();
   102|
   103|  // Tier 1: clean parse — fast path for fully compliant outputs.
   104|  try {
   105|    return JSON.parse(cleaned);
   106|  } catch {
   107|    // fall through
   108|  }
   109|
   110|  // Tier 2: scan forward to the FIRST `{` and parse from there. Recovers the
   111|  // preamble-then-JSON pattern reasoning models emit. A backward scan from
   112|  // the last `{` was considered but rejected: it silently returns the wrong
   113|  // object when the prose contains a brace-bearing example after the real
   114|  // payload (e.g. `{"actual":1}\nFor example: {"x":2}` would yield `{x:2}`),
   115|  // breaking the conservative-failure contract callers rely on.
   116|  const firstBrace = cleaned.indexOf('{');
   117|  if (firstBrace > 0) {
   118|    try {
   119|      return JSON.parse(cleaned.slice(firstBrace));
   120|    } catch {
   121|      // fall through
   122|    }
   123|  }
   124|
   125|  return undefined;
   126|}
   127|
   128|/**
   129| * Pure mapper from Pi's `AgentSessionEvent` → zero-or-more Archon `MessageChunk`s.
   130| *
   131| * Most Pi events map 1:1 or are skipped. Tool execution is split across
   132| * `tool_execution_start` / `tool_execution_end`; the start yields `tool` with
   133| * `toolCallId`, the end yields `tool_result` matched by the same id.
   134| *
   135| * Events deliberately skipped in v1:
   136| *  - turn_start / turn_end, message_start / message_end (redundant with deltas)
   137| *  - text_start / text_end / thinking_start / thinking_end (boundaries only)
   138| *  - compaction_start / compaction_end (auto-compaction opaque to Archon)
   139| *  - queue_update (single-prompt sessions only)
   140| *  - auto_retry_end (retry_start communicates the retry sufficiently)
   141| */
   142|export function mapPiEvent(event: AgentSessionEvent): MessageChunk[] {
   143|  switch (event.type) {
   144|    case 'message_update': {
   145|      const amEvent = event.assistantMessageEvent;
   146|      if (amEvent.type === 'text_delta') {
   147|        return [{ type: 'assistant', content: amEvent.delta }];
   148|      }
   149|      if (amEvent.type === 'thinking_delta') {
   150|        return [{ type: 'thinking', content: amEvent.delta }];
   151|      }
   152|      return [];
   153|    }
   154|    case 'tool_execution_start':
   155|      return [
   156|        {
   157|          type: 'tool',
   158|          toolName: event.toolName,
   159|          toolInput:
   160|            typeof event.args === 'object' && event.args !== null
   161|              ? (event.args as Record<string, unknown>)
   162|              : {},
   163|          toolCallId: event.toolCallId,
   164|        },
   165|      ];
   166|    case 'tool_execution_end': {
   167|      const chunks: MessageChunk[] = [];
   168|      if (event.isError) {
   169|        chunks.push({
   170|          type: 'system',
   171|          content: `⚠️ Tool ${event.toolName} failed`,
   172|        });
   173|      }
   174|      chunks.push({
   175|        type: 'tool_result',
   176|        toolName: event.toolName,
   177|        toolOutput: serializeToolResult(event.result),
   178|        toolCallId: event.toolCallId,
   179|      });
   180|      return chunks;
   181|    }
   182|    case 'agent_end':
   183|      return [buildResultChunk(event.messages)];
   184|    case 'auto_retry_start':
   185|      return [
   186|        {
   187|          type: 'system',
   188|          content: `⚠️ retry ${event.attempt}/${event.maxAttempts}: ${event.errorMessage}`,
   189|        },
   190|      ];
   191|    default:
   192|      return [];
   193|  }
   194|}
   195|
   196|/** Lets the UI stub push notifications into the session's chunk queue. */
   197|export interface BridgeNotifier {
   198|  setEmitter(fn: ((chunk: MessageChunk) => void) | undefined): void;
   199|}
   200|
   201|export async function* bridgeSession(
   202|  session: AgentSession,
   203|  prompt: string,
   204|  abortSignal?: AbortSignal,
   205|  jsonSchema?: Record<string, unknown>,
   206|  uiBridge?: BridgeNotifier
   207|): AsyncGenerator<MessageChunk> {
   208|  const queue = new AsyncQueue<BridgeQueueItem>();
   209|  uiBridge?.setEmitter(chunk => {
   210|    queue.push({ kind: 'chunk', chunk });
   211|  });
   212|  // Best-effort structured-output buffer. Only accumulates when the caller
   213|  // requested a JSON schema; otherwise stays empty and the terminal chunk
   214|  // passes through untouched.
   215|  const wantsStructured = jsonSchema !== undefined;
   216|  let assistantBuffer = '';
   217|
   218|  const unsubscribe = session.subscribe((event: AgentSessionEvent) => {
   219|    try {
   220|      for (const chunk of mapPiEvent(event)) {
   221|        if (wantsStructured && chunk.type === 'assistant') {
   222|          assistantBuffer += chunk.content;
   223|        }
   224|        queue.push({ kind: 'chunk', chunk });
   225|      }
   226|    } catch (err) {
   227|      queue.push({ kind: 'error', error: err as Error });
   228|    }
   229|  });
   230|
   231|  const onAbort = (): void => {
   232|    void session.abort().catch((err: unknown) => {
   233|      // Abort is best-effort — failures are recoverable via the dispose()
   234|      // call in the `finally` below. But log at debug so a regression in
   235|      // Pi's abort path doesn't silently disappear.
   236|      getLog().debug({ err }, 'pi.event-bridge.abort_failed');
   237|    });
   238|  };
   239|  if (abortSignal) {
   240|    if (abortSignal.aborted) {
   241|      onAbort();
   242|    } else {
   243|      abortSignal.addEventListener('abort', onAbort, { once: true });
   244|    }
   245|  }
   246|
   247|  const promptPromise = session.prompt(prompt).then(
   248|    () => {
   249|      queue.push({ kind: 'done' });
   250|    },
   251|    (err: unknown) => {
   252|      queue.push({ kind: 'error', error: err as Error });
   253|    }
   254|  );
   255|
   256|  try {
   257|    for await (const item of queue) {
   258|      if (item.kind === 'done') return;
   259|      if (item.kind === 'error') throw item.error;
   260|      // Annotate the terminal result chunk with Pi's session UUID so Archon's
   261|      // orchestrator can pass it back as `resumeSessionId` on the next call.
   262|      // Pi's session.sessionId is always a UUID (even for in-memory); we emit
   263|      // it unconditionally and let the caller decide whether resume is
   264|      // meaningful (capability-gated at the registry level).
   265|      if (item.chunk.type === 'result') {
   266|        let terminal: MessageChunk = item.chunk;
   267|        if (session.sessionId) {
   268|          terminal = { ...terminal, sessionId: session.sessionId };
   269|        }
   270|        // Best-effort structured output: parse the accumulated assistant
   271|        // transcript as JSON and attach. On parse failure, leave it off —
   272|        // the dag-executor's existing dag.structured_output_missing path
   273|        // warns and downstream $node.output.field refs degrade to '' instead
   274|        // of propagating bogus data.
   275|        if (wantsStructured) {
   276|          const parsed = tryParseStructuredOutput(assistantBuffer);
   277|          if (parsed !== undefined) {
   278|            terminal = { ...terminal, structuredOutput: parsed };
   279|          } else {
   280|            getLog().warn(
   281|              { bufferLength: assistantBuffer.length },
   282|              'pi.event-bridge.structured_output_parse_failed'
   283|            );
   284|          }
   285|        }
   286|        yield terminal;
   287|      } else {
   288|        yield item.chunk;
   289|      }
   290|    }
   291|  } finally {
   292|    // Close the queue first so any producer push() still in flight becomes
   293|    // a no-op and pending iterate() waiters resolve — otherwise a consumer
   294|    // abort mid-iteration would leak this generator on the promise forever.
   295|    queue.close();
   296|    uiBridge?.setEmitter(undefined);
   297|    unsubscribe();
   298|    if (abortSignal) {
   299|      abortSignal.removeEventListener('abort', onAbort);
   300|    }
   301|    try {
   302|      session.dispose();
   303|    } catch (err: unknown) {
   304|      // Dispose is defensive — session may already be torn down. Log at
   305|      // debug so SDK regressions surface without polluting normal output.
   306|      getLog().debug({ err }, 'pi.event-bridge.dispose_failed');
   307|    }
   308|    // Ensure the prompt promise settles so callers see no dangling work.
   309|    await promptPromise.catch(() => {
   310|      /* errors already surfaced through the queue */
   311|    });
   312|  }
   313|}
